INSERT INTO help_answers (slug, question, answer, href, fallback_href, pages, words, position) VALUES
  ('add-board', '{"en": "How do I add another board?", "nl": "Hoe voeg ik nog een bord toe?", "de": "Wie füge ich ein weiteres Board hinzu?", "es": "¿Cómo añado otro tablero?", "fr": "Comment ajouter un autre tableau ?", "pt": "Como adiciono outro quadro?", "tlh": "chay'' latlh ''echlet vIchel?"}'::jsonb, '{"en": "Boards are added by organization admins. While a project has one board, use New board on the project page; after that, it’s in Edit project → Boards.", "nl": "Borden worden toegevoegd door organisatiebeheerders. Zolang een project één bord heeft, gebruik je Nieuw bord op de projectpagina; daarna zit het in Project bewerken → Borden.", "de": "Boards werden von Organisations-Admins hinzugefügt. Solange ein Projekt ein Board hat, nutze „Neues Board“ auf der Projektseite; danach findest du es unter Projekt bearbeiten → Boards.", "es": "Los tableros los añaden los administradores de la organización. Mientras un proyecto tenga un solo tablero, usa Nuevo tablero en la página del proyecto; después, está en Editar proyecto → Tableros.", "fr": "Les tableaux sont ajoutés par les administrateurs de l’organisation. Tant qu’un projet n’a qu’un seul tableau, utilisez Nouveau tableau sur la page du projet ; ensuite, c’est dans Modifier le projet → Tableaux.", "pt": "Os quadros são adicionados por admins da organização. Enquanto um projeto tem um quadro, use Novo quadro na página do projeto; depois disso, fica em Editar projeto → Quadros.", "tlh": "''echletmey chel ghom''a'' loHwI''pu''. wa'' ''echlet ghaj jInmol, vaj jInmol nachDaq ''echlet chu'' yIlo''; ghIq jInmol yIchoH → ''echletmeyDaq tu''lu''."}'::jsonb, '/projects/[project]/edit', '', ARRAY['project']::text[], 'new board create second third team', 0),
  ('new-ticket', '{"en": "How do I create a ticket?", "nl": "Hoe maak ik een ticket aan?", "de": "Wie erstelle ich ein Ticket?", "es": "¿Cómo creo un ticket?", "fr": "Comment créer un ticket ?", "pt": "Como crio um ticket?", "tlh": "chay'' ticket vIchenmoH?"}'::jsonb, '{"en": "On a board, use + Add ticket under a column. New ticket in the header (on the dashboard, project and board pages) adds one to the project’s backlog.", "nl": "Gebruik op een bord + Ticket toevoegen onder een kolom. Nieuw ticket bovenaan (op het dashboard en op project- en bordpagina’s) zet er een in de backlog van het project.", "de": "Nutze auf einem Board „+ Ticket hinzufügen“ unter einer Spalte. „Neues Ticket“ in der Kopfzeile (auf Dashboard-, Projekt- und Board-Seiten) fügt eins zum Backlog des Projekts hinzu.", "es": "En un tablero, usa + Añadir ticket debajo de una columna. Nuevo ticket en la cabecera (en el panel, y en las páginas de proyecto y tablero) añade uno al backlog del proyecto.", "fr": "Sur un tableau, utilisez + Ajouter un ticket sous une colonne. Nouveau ticket dans l’en-tête (sur les pages du tableau de bord, du projet et du tableau) en ajoute un au backlog du projet.", "pt": "Em um quadro, use + Adicionar ticket abaixo de uma coluna. Novo ticket no cabeçalho (nas páginas de painel, projeto e quadro) adiciona um ao backlog do projeto.", "tlh": "''echletDaq, tut bIngDaq + ticket yIchel yIlo''. nachDaq ticket chu'' (SeHlaw, jInmol, ''echlet navmeyDaq) jInmol backlogDaq wa'' chel."}'::jsonb, '/dashboard', '', ARRAY['board', 'project', 'dashboard']::text[], 'new ticket create add issue', 1),
  ('backlog', '{"en": "Where’s the backlog?", "nl": "Waar is de backlog?", "de": "Wo ist das Backlog?", "es": "¿Dónde está el backlog?", "fr": "Où est le backlog ?", "pt": "Onde fica o backlog?", "tlh": "nuqDaq backlog tu''lu''?"}'::jsonb, '{"en": "On the project page, in the Backlog tab.", "nl": "Op de projectpagina, in het tabblad Backlog.", "de": "Auf der Projektseite im Tab „Backlog“.", "es": "En la página del proyecto, en la pestaña Backlog.", "fr": "Sur la page du projet, dans l’onglet Backlog.", "pt": "Na página do projeto, na aba Backlog.", "tlh": "jInmol nachDaq, Backlog SopDaq."}'::jsonb, '/projects/[project]', '', ARRAY['project']::text[], 'backlog', 2),
  ('sprint', '{"en": "How do I start or close a sprint?", "nl": "Hoe start of sluit ik een sprint?", "de": "Wie starte oder schließe ich einen Sprint ab?", "es": "¿Cómo inicio o cierro un sprint?", "fr": "Comment démarrer ou clôturer un sprint ?", "pt": "Como inicio ou fecho uma sprint?", "tlh": "chay'' sprint vItagh pagh vISoQmoH?"}'::jsonb, '{"en": "On the board’s sprint bar: Start sprint, and Close sprint once it’s running. Admins and the board’s team leads can.", "nl": "In de sprintbalk van het bord: Sprint starten, en Sprint afsluiten zodra hij loopt. Beheerders en de teamleiders van het bord kunnen dat.", "de": "In der Sprintleiste des Boards: „Sprint starten“ und „Sprint abschließen“, sobald er läuft. Das können Admins und die Teamleitung des Boards.", "es": "En la barra de sprint del tablero: Empezar sprint, y Cerrar sprint cuando esté en curso. Pueden hacerlo los administradores y los líderes de equipo del tablero.", "fr": "Dans la barre de sprint du tableau : Démarrer le sprint, puis Clôturer le sprint une fois qu’il est en cours. Les administrateurs et les responsables d’équipe du tableau le peuvent.", "pt": "Na barra de sprint do quadro: Iniciar sprint, e Fechar sprint quando ela estiver em andamento. Admins e os líderes de equipe do quadro podem fazer isso.", "tlh": "''echlet sprint tlheghDaq: sprint yItagh, ''ej ta''lI''DI'' sprint yISoQmoH. loHwI''pu'' ''echlet beq DevwI''pu'' je laH."}'::jsonb, '/boards/[board]', '', ARRAY['board']::text[], 'sprint start close end', 3),
  ('standup', '{"en": "How do I run a standup?", "nl": "Hoe houd ik een stand-up?", "de": "Wie führe ich ein Standup durch?", "es": "¿Cómo dirijo un standup?", "fr": "Comment animer un standup ?", "pt": "Como conduzo um standup?", "tlh": "chay'' Qam ghom vIDev?"}'::jsonb, '{"en": "On the board, click Standup, then Start once everyone has joined.", "nl": "Klik op het bord op Stand-up en daarna op Starten zodra iedereen er is.", "de": "Klicke auf dem Board auf „Standup“ und dann auf „Starten“, sobald alle beigetreten sind.", "es": "En el tablero, haz clic en Standup y luego en Empezar cuando todos se hayan unido.", "fr": "Sur le tableau, cliquez sur Standup, puis sur Démarrer une fois que tout le monde a rejoint.", "pt": "No quadro, clique em Standup e depois em Iniciar quando todos tiverem entrado.", "tlh": "''echletDaq, Qam ghom yI''uy, ghIq Hoch ghot muvDI'' yItagh yI''uy."}'::jsonb, '/docs/standup', '', ARRAY['board']::text[], 'standup daily meeting', 4),
  ('edit-board', '{"en": "How do I change a board’s columns or WIP limits?", "nl": "Hoe wijzig ik de kolommen of WIP-limieten van een bord?", "de": "Wie ändere ich die Spalten oder WIP-Limits eines Boards?", "es": "¿Cómo cambio las columnas o los límites WIP de un tablero?", "fr": "Comment modifier les colonnes ou les limites WIP d’un tableau ?", "pt": "Como altero as colunas ou os limites de WIP de um quadro?", "tlh": "chay'' ''echlet tutmey pagh WIP veHmey vIchoH?"}'::jsonb, '{"en": "Open the board → Edit board. Drag columns to reorder them, set WIP limits, and change the estimate scale. Admins and the board’s team leads can edit it.", "nl": "Open het bord → Bord bewerken. Sleep kolommen om de volgorde te wijzigen, stel WIP-limieten in en wijzig de schattingsschaal. Beheerders en de teamleiders van het bord kunnen het bewerken.", "de": "Öffne das Board → Board bearbeiten. Zieh Spalten, um sie umzusortieren, setze WIP-Limits und ändere die Schätzskala. Admins und die Teamleitung des Boards können es bearbeiten.", "es": "Abre el tablero → Editar tablero. Arrastra las columnas para reordenarlas, define límites WIP y cambia la escala de estimación. Pueden editarlo los administradores y los líderes de equipo del tablero.", "fr": "Ouvrez le tableau → Modifier le tableau. Faites glisser les colonnes pour les réorganiser, définissez les limites WIP et changez l’échelle d’estimation. Les administrateurs et les responsables d’équipe du tableau peuvent le modifier.", "pt": "Abra o quadro → Editar quadro. Arraste as colunas para reordená-las, defina limites de WIP e altere a escala de estimativa. Admins e os líderes de equipe do quadro podem editá-lo.", "tlh": "''echlet yIpoSmoH → ''echlet yIchoH. DamIwmeH tutmey tIlIS, WIP veHmey tIcher, pIHmeH juvwI'' yIchoH. loHwI''pu'' ''echlet beq DevwI''pu'' je choHlaH."}'::jsonb, '/boards/[board]/edit', '', ARRAY['board']::text[], 'columns wip limit estimates scale settings rename', 5),
  ('refine', '{"en": "How do I plan the next sprints?", "nl": "Hoe plan ik de volgende sprints?", "de": "Wie plane ich die nächsten Sprints?", "es": "¿Cómo planifico los próximos sprints?", "fr": "Comment planifier les prochains sprints ?", "pt": "Como planejo as próximas sprints?", "tlh": "chay'' sprintmey veb vInab?"}'::jsonb, '{"en": "On the project page’s Backlog tab, use Refine. Each sprint holds the team’s velocity plus 10%; more needs approval from an admin or the team lead.", "nl": "Start een refinement vanuit het tabblad Backlog op de projectpagina. Elke sprint bevat de velocity van het team plus 10%; meer heeft goedkeuring nodig van een beheerder of de teamleider.", "de": "Nutze im Tab „Backlog“ der Projektseite „Refinement“. Jeder Sprint fasst die Velocity des Teams plus 10 %; mehr braucht die Genehmigung eines Admins oder der Teamleitung.", "es": "En la pestaña Backlog de la página del proyecto, usa Refinar. Cada sprint admite la velocidad del equipo más un 10 %; más requiere la aprobación de un administrador o del líder del equipo.", "fr": "Dans l’onglet Backlog de la page du projet, utilisez Affiner. Chaque sprint contient la vélocité de l’équipe plus 10 % ; au-delà, l’approbation d’un administrateur ou du responsable d’équipe est nécessaire.", "pt": "Na aba Backlog da página do projeto, use Refinar. Cada sprint comporta a velocidade da equipe mais 10%; mais do que isso precisa da aprovação de um admin ou do líder da equipe.", "tlh": "jInmol nach Backlog SopDaq, Dubghach yIlo''. Hoch sprint ngaS beq Do ''ej 10% latlh; latlh DaneHchugh loHwI'' pagh beq DevwI'' chaw'' poQ."}'::jsonb, '/docs/refinement', '', ARRAY['project']::text[], 'plan refine refinement capacity approve', 6),
  ('backlog-to-board', '{"en": "How do I move a backlog ticket onto a board?", "nl": "Hoe zet ik een backlogticket op een bord?", "de": "Wie verschiebe ich ein Backlog-Ticket auf ein Board?", "es": "¿Cómo muevo un ticket del backlog a un tablero?", "fr": "Comment déplacer un ticket du backlog sur un tableau ?", "pt": "Como movo um ticket do backlog para um quadro?", "tlh": "chay'' backlog ticket ''echletDaq vIvIHmoH?"}'::jsonb, '{"en": "Open the ticket → Edit → Move to board…, or use Move to board… in Refine. Boards with estimates ask for one first. Admins and the project’s team leads can.", "nl": "Open het ticket → Bewerken → Naar bord verplaatsen…, of gebruik Naar bord verplaatsen… tijdens refinement. Borden met schattingen vragen er eerst een. Beheerders en de teamleiders van het project kunnen dat.", "de": "Öffne das Ticket → Bearbeiten → Auf Board verschieben… oder nutze „Auf Board verschieben…“ im Refinement. Boards mit Schätzungen fragen zuerst nach einer. Das können Admins und die Teamleitung des Projekts.", "es": "Abre el ticket → Editar → Mover al tablero…, o usa Mover al tablero… en Refinar. Los tableros con estimaciones piden una primero. Pueden hacerlo los administradores y los líderes de equipo del proyecto.", "fr": "Ouvrez le ticket → Modifier → Déplacer vers le tableau…, ou utilisez Déplacer vers le tableau… dans Affiner. Les tableaux avec estimations en demandent une d’abord. Les administrateurs et les responsables d’équipe du projet le peuvent.", "pt": "Abra o ticket → Editar → Mover para o quadro…, ou use Mover para o quadro… no Refinar. Quadros com estimativas pedem uma antes. Admins e os líderes de equipe do projeto podem fazer isso.", "tlh": "ticket yIpoSmoH → yIchoH → ''echletDaq yIvIHmoH…, pagh DubghachDaq ''echletDaq yIvIHmoH… yIlo''. ''echletmey pIHbogh pIHghach tlhob wa''DIch. loHwI''pu'' jInmol beq DevwI''pu'' je laH."}'::jsonb, '/projects/[project]', '', ARRAY['project']::text[], 'move board backlog plan', 7),
  ('other-board', '{"en": "How do I move a ticket to another board?", "nl": "Hoe verplaats ik een ticket naar een ander bord?", "de": "Wie verschiebe ich ein Ticket auf ein anderes Board?", "es": "¿Cómo muevo un ticket a otro tablero?", "fr": "Comment déplacer un ticket vers un autre tableau ?", "pt": "Como movo um ticket para outro quadro?", "tlh": "chay'' latlh ''echletDaq ticket vIvIHmoH?"}'::jsonb, '{"en": "Open the ticket → Edit → Move to board… and pick the board; open sub-tickets on this board go with it. Admins and the project’s team leads can.", "nl": "Open het ticket → Bewerken → Naar bord verplaatsen… en kies het bord; open subtickets op dit bord gaan mee. Beheerders en de teamleiders van het project kunnen dat.", "de": "Öffne das Ticket → Bearbeiten → Auf Board verschieben… und wähle das Board; offene Untertickets auf diesem Board gehen mit. Das können Admins und die Teamleitung des Projekts.", "es": "Abre el ticket → Editar → Mover al tablero… y elige el tablero; los subtickets abiertos de este tablero se van con él. Pueden hacerlo los administradores y los líderes de equipo del proyecto.", "fr": "Ouvrez le ticket → Modifier → Déplacer vers le tableau… et choisissez le tableau ; les sous-tickets ouverts sur ce tableau suivent. Les administrateurs et les responsables d’équipe du projet le peuvent.", "pt": "Abra o ticket → Editar → Mover para o quadro… e escolha o quadro; os sub-tickets abertos neste quadro vão junto. Admins e os líderes de equipe do projeto podem fazer isso.", "tlh": "ticket yIpoSmoH → yIchoH → ''echletDaq yIvIHmoH… ''ej ''echlet yIwIv; ''echletvamDaq ticket puqmey poSbogh tlha''. loHwI''pu'' jInmol beq DevwI''pu'' je laH."}'::jsonb, '/projects/[project]', '', ARRAY['board']::text[], 'move transfer another board', 8),
  ('next-sprints', '{"en": "Where can I see what’s planned for the next sprint?", "nl": "Waar zie ik wat er voor de volgende sprint gepland is?", "de": "Wo sehe ich, was für den nächsten Sprint geplant ist?", "es": "¿Dónde puedo ver lo planificado para el próximo sprint?", "fr": "Où puis-je voir ce qui est prévu pour le prochain sprint ?", "pt": "Onde vejo o que está planejado para a próxima sprint?", "tlh": "nuqDaq sprint vebvaD nablu''pu''bogh vIleghlaH?"}'::jsonb, '{"en": "On the board, open Next sprints. Planned tickets join the board when their sprint starts; until then the backlog hides them unless you choose Planned.", "nl": "Open op het bord Volgende sprints. Geplande tickets komen op het bord zodra hun sprint start; tot die tijd verbergt de backlog ze, tenzij je Gepland kiest.", "de": "Öffne auf dem Board „Nächste Sprints“. Geplante Tickets kommen aufs Board, wenn ihr Sprint startet; bis dahin blendet das Backlog sie aus, außer du wählst „Geplant“.", "es": "En el tablero, abre Próximos sprints. Los tickets planificados se incorporan al tablero cuando empieza su sprint; hasta entonces el backlog los oculta salvo que elijas Planificados.", "fr": "Sur le tableau, ouvrez Prochains sprints. Les tickets planifiés rejoignent le tableau au démarrage de leur sprint ; d’ici là, le backlog les masque sauf si vous choisissez Planifiés.", "pt": "No quadro, abra Próximas sprints. Os tickets planejados entram no quadro quando a sprint deles começa; até lá, o backlog os oculta, a menos que você escolha Planejados.", "tlh": "''echletDaq, sprintmey veb yIpoSmoH. sprintchaj taghDI'' ''echletDaq muv ticketmey nablu''pu''bogh; ret So'' backlog nablu''pu''bogh DawIvbe''chugh."}'::jsonb, '/boards/[board]?view=next', '', ARRAY['board', 'project']::text[], 'next sprint planned upcoming future', 9),
  ('archived-boards', '{"en": "Where are archived boards?", "nl": "Waar zijn gearchiveerde borden?", "de": "Wo sind archivierte Boards?", "es": "¿Dónde están los tableros archivados?", "fr": "Où sont les tableaux archivés ?", "pt": "Onde ficam os quadros arquivados?", "tlh": "nuqDaq ''echletmey ngaSlu''pu''bogh tu''lu''?"}'::jsonb, '{"en": "In Edit project → Archived boards. Restore one from its banner.", "nl": "In Project bewerken → Gearchiveerde borden. Herstel er een via de balk bovenaan.", "de": "Unter Projekt bearbeiten → Archivierte Boards. Stelle eins über sein Banner wieder her.", "es": "En Editar proyecto → Tableros archivados. Restaura uno desde su banner.", "fr": "Dans Modifier le projet → Tableaux archivés. Restaurez-en un depuis sa bannière.", "pt": "Em Editar projeto → Quadros arquivados. Restaure um pelo banner dele.", "tlh": "jInmol yIchoH → ''echletmey ngaSlu''pu''bogh. ghItlhDaj vo'' wa'' yIcheghmoH."}'::jsonb, '/projects/[project]/archived', '', ARRAY['project']::text[], 'archived restore board', 10),
  ('key-prefix', '{"en": "How do I change the ticket key (like TL-)?", "nl": "Hoe wijzig ik de ticketcode (zoals TL-)?", "de": "Wie ändere ich den Ticketschlüssel (z. B. TL-)?", "es": "¿Cómo cambio la clave de los tickets (como TL-)?", "fr": "Comment changer la clé des tickets (comme TL-) ?", "pt": "Como altero a chave do ticket (como TL-)?", "tlh": "chay'' ticket ngaQHa''moHwI'' (TL- rur) vIchoH?"}'::jsonb, '{"en": "In Edit project → Ticket keys. Organization admins only.", "nl": "In Project bewerken → Ticketcodes. Alleen organisatiebeheerders.", "de": "Unter Projekt bearbeiten → Ticketschlüssel. Nur Organisations-Admins.", "es": "En Editar proyecto → Claves de ticket. Solo administradores de la organización.", "fr": "Dans Modifier le projet → Clés des tickets. Administrateurs de l’organisation uniquement.", "pt": "Em Editar projeto → Chaves de ticket. Somente admins da organização.", "tlh": "jInmol yIchoH → ticket ngaQHa''moHwI''mey. ghom''a'' loHwI''pu'' neH."}'::jsonb, '/projects/[project]/edit', '', ARRAY['project']::text[], 'prefix key ticket number', 11),
  ('archive-board', '{"en": "How do I archive or delete a board?", "nl": "Hoe archiveer of verwijder ik een bord?", "de": "Wie archiviere oder lösche ich ein Board?", "es": "¿Cómo archivo o elimino un tablero?", "fr": "Comment archiver ou supprimer un tableau ?", "pt": "Como arquivo ou excluo um quadro?", "tlh": "chay'' ''echlet vIngaS pagh vIQaw''?"}'::jsonb, '{"en": "Open the board → Edit board → More. A board that’s been used can be archived (admins and its team leads); one that never was can be deleted (admins).", "nl": "Open het bord → Bord bewerken → Meer. Een gebruikt bord kun je archiveren (beheerders en de teamleiders); een ongebruikt bord kun je verwijderen (beheerders).", "de": "Öffne das Board → Board bearbeiten → Mehr. Ein genutztes Board kann archiviert werden (Admins und seine Teamleitung); eins, das nie genutzt wurde, kann gelöscht werden (Admins).", "es": "Abre el tablero → Editar tablero → Más. Un tablero que se ha usado se puede archivar (administradores y sus líderes de equipo); uno que nunca se usó se puede eliminar (administradores).", "fr": "Ouvrez le tableau → Modifier le tableau → Plus. Un tableau qui a été utilisé peut être archivé (administrateurs et ses responsables d’équipe) ; un tableau jamais utilisé peut être supprimé (administrateurs).", "pt": "Abra o quadro → Editar quadro → Mais. Um quadro que já foi usado pode ser arquivado (admins e os líderes de equipe dele); um que nunca foi usado pode ser excluído (admins).", "tlh": "''echlet yIpoSmoH → ''echlet yIchoH → latlh. ''echlet lo''lu''pu''bogh ngaSlu''laH (loHwI''pu'' beq DevwI''pu'' je); not lo''lu''pu''bogh Qaw''lu''laH (loHwI''pu'')."}'::jsonb, '/boards/[board]/edit', '', ARRAY['board']::text[], 'remove archive delete board', 12),
  ('templates', '{"en": "Can I reuse a board’s setup?", "nl": "Kan ik de opzet van een bord hergebruiken?", "de": "Kann ich die Einrichtung eines Boards wiederverwenden?", "es": "¿Puedo reutilizar la configuración de un tablero?", "fr": "Puis-je réutiliser la configuration d’un tableau ?", "pt": "Posso reutilizar a configuração de um quadro?", "tlh": "''echlet mIw vIlo''qa''laH''a''?"}'::jsonb, '{"en": "Yes: Edit board → More → Save as template (columns, WIP limits, style and estimates, not tickets). Pick it in the Template list when making a new board. Admins only.", "nl": "Ja: Bord bewerken → Meer → Opslaan als sjabloon (kolommen, WIP-limieten, stijl en schattingen, geen tickets). Kies het in de lijst Sjabloon bij een nieuw bord. Alleen beheerders.", "de": "Ja: Board bearbeiten → Mehr → Als Vorlage speichern (Spalten, WIP-Limits, Stil und Schätzungen, keine Tickets). Wähle sie beim Erstellen eines neuen Boards in der Liste „Vorlage“. Nur Admins.", "es": "Sí: Editar tablero → Más → Guardar como plantilla (columnas, límites WIP, estilo y estimaciones, no tickets). Elígela en la lista Plantilla al crear un tablero nuevo. Solo administradores.", "fr": "Oui : Modifier le tableau → Plus → Enregistrer comme modèle (colonnes, limites WIP, style et estimations, pas les tickets). Choisissez-le dans la liste Modèle lors de la création d’un nouveau tableau. Administrateurs uniquement.", "pt": "Sim: Editar quadro → Mais → Salvar como modelo (colunas, limites de WIP, estilo e estimativas, não os tickets). Escolha-o na lista Modelo ao criar um novo quadro. Somente admins.", "tlh": "HIja'': ''echlet yIchoH → latlh → mIllogh Daq yIpol (tutmey, WIP veHmey, mIw, pIHghachmey je, ticketmey ghobe''). ''echlet chu'' DachenmoHDI'' mIllogh tetlhDaq yIwIv. loHwI''pu'' neH."}'::jsonb, '/boards/[board]/edit', '', ARRAY['board']::text[], 'template copy setup', 13),
  ('new-project', '{"en": "How do I create a project?", "nl": "Hoe maak ik een project aan?", "de": "Wie erstelle ich ein Projekt?", "es": "¿Cómo creo un proyecto?", "fr": "Comment créer un projet ?", "pt": "Como crio um projeto?", "tlh": "chay'' jInmol vIchenmoH?"}'::jsonb, '{"en": "Use New project on the dashboard. Your plan sets how many projects you can have (Free 1, Pro 5).", "nl": "Gebruik Nieuw project op het dashboard. Je abonnement bepaalt hoeveel projecten je kunt hebben (Free 1, Pro 5).", "de": "Nutze „Neues Projekt“ auf dem Dashboard. Dein Tarif legt fest, wie viele Projekte du haben kannst (Free 1, Pro 5).", "es": "Usa Nuevo proyecto en el panel. Tu plan determina cuántos proyectos puedes tener (Free 1, Pro 5).", "fr": "Utilisez Nouveau projet sur le tableau de bord. Votre offre détermine le nombre de projets possibles (Free 1, Pro 5).", "pt": "Use Novo projeto no painel. Seu plano define quantos projetos você pode ter (Free 1, Pro 5).", "tlh": "SeHlawDaq jInmol chu'' yIlo''. jInmolmey ''ar DaghajlaH ''e'' cher nablIj (Free 1, Pro 5)."}'::jsonb, '/dashboard', '', ARRAY['dashboard']::text[], 'new project create', 14),
  ('my-work', '{"en": "Where can I see all my tickets?", "nl": "Waar zie ik al mijn tickets?", "de": "Wo sehe ich alle meine Tickets?", "es": "¿Dónde puedo ver todos mis tickets?", "fr": "Où puis-je voir tous mes tickets ?", "pt": "Onde vejo todos os meus tickets?", "tlh": "nuqDaq Hoch ticketmeywIj vIleghlaH?"}'::jsonb, '{"en": "My work lists what’s assigned to you and what you raised, across every board.", "nl": "Mijn werk toont wat aan jou is toegewezen en wat je hebt aangemaakt, over alle borden.", "de": "„Meine Arbeit“ listet über alle Boards auf, was dir zugewiesen ist und was du erstellt hast.", "es": "Mi trabajo muestra lo que tienes asignado y lo que has creado, en todos los tableros.", "fr": "Mon travail liste ce qui vous est assigné et ce que vous avez soumis, sur tous les tableaux.", "pt": "Meu trabalho lista o que está atribuído a você e o que você abriu, em todos os quadros.", "tlh": "Hoch ''echletDaq SoHvaD noblu''bogh ''ej DachenmoHbogh ''ang Qu''wIj."}'::jsonb, '/my-work', '', ARRAY['dashboard']::text[], 'my tickets assigned mine', 15),
  ('sub-tickets', '{"en": "How do I add sub-tickets?", "nl": "Hoe voeg ik subtickets toe?", "de": "Wie füge ich Untertickets hinzu?", "es": "¿Cómo añado subtickets?", "fr": "Comment ajouter des sous-tickets ?", "pt": "Como adiciono sub-tickets?", "tlh": "chay'' ticket puqmey vIchel?"}'::jsonb, '{"en": "Open the ticket’s own page; under Sub-tickets use Add a sub-ticket… or New sub-ticket….", "nl": "Open de pagina van het ticket; gebruik onder Subtickets Subticket toevoegen… of Nieuw subticket….", "de": "Öffne die eigene Seite des Tickets; nutze unter Untertickets „Unterticket hinzufügen…“ oder „Neues Unterticket…“.", "es": "Abre la página propia del ticket; en Subtickets usa Añadir un subticket… o Nuevo subticket….", "fr": "Ouvrez la page propre du ticket ; sous Sous-tickets, utilisez Ajouter un sous-ticket… ou Nouveau sous-ticket….", "pt": "Abra a página do próprio ticket; em Sub-tickets, use Adicionar um sub-ticket… ou Novo sub-ticket….", "tlh": "ticket nav yIpoSmoH; ticket puqmey bIngDaq ticket puq yIchel… pagh ticket puq chu''… yIlo''."}'::jsonb, '/docs/epics', '', '{}'::text[], 'sub task subtask child parent', 16),
  ('epics', '{"en": "What’s an epic?", "nl": "Wat is een epic?", "de": "Was ist ein Epic?", "es": "¿Qué es una épica?", "fr": "Qu’est-ce qu’une epic ?", "pt": "O que é um épico?", "tlh": "nuq ''oH lut''a''?"}'::jsonb, '{"en": "A large piece of work across boards. Set a ticket’s type to Epic; epics live in the backlog and have their own tab on the project page.", "nl": "Een groot stuk werk over meerdere borden. Zet het type van een ticket op Epic; epics staan in de backlog en hebben een eigen tabblad op de projectpagina.", "de": "Ein großes Arbeitspaket über mehrere Boards hinweg. Setze den Typ eines Tickets auf Epic; Epics liegen im Backlog und haben auf der Projektseite einen eigenen Tab.", "es": "Un trabajo grande que abarca varios tableros. Pon el tipo de un ticket en Épica; las épicas viven en el backlog y tienen su propia pestaña en la página del proyecto.", "fr": "Un gros chantier couvrant plusieurs tableaux. Définissez le type d’un ticket sur Epic ; les epics vivent dans le backlog et ont leur propre onglet sur la page du projet.", "pt": "Um trabalho grande que abrange vários quadros. Defina o tipo de um ticket como Épico; os épicos ficam no backlog e têm uma aba própria na página do projeto.", "tlh": "''echletmey Hoch Qu'' tIn. ticket Segh yIcher Epic; backlogDaq yIn lut''a''mey, ''ej jInmol nachDaq lut''a'' Sopmey ghaj."}'::jsonb, '/docs/epics', '', ARRAY['project']::text[], 'epic', 17),
  ('blocked', '{"en": "How do I mark a ticket as blocked?", "nl": "Hoe markeer ik een ticket als geblokkeerd?", "de": "Wie markiere ich ein Ticket als blockiert?", "es": "¿Cómo marco un ticket como bloqueado?", "fr": "Comment marquer un ticket comme bloqué ?", "pt": "Como marco um ticket como bloqueado?", "tlh": "chay'' ticket botlu''bogh vIper?"}'::jsonb, '{"en": "On the ticket’s page, under Dependencies → Blocked by, use Add a blocker…. A blocked ticket can’t be claimed.", "nl": "Gebruik op de ticketpagina, onder Afhankelijkheden → Geblokkeerd door, Blokkade toevoegen…. Een geblokkeerd ticket kan niet worden opgepakt.", "de": "Nutze auf der Ticketseite unter Abhängigkeiten → Blockiert durch „Blocker hinzufügen…“. Ein blockiertes Ticket kann nicht übernommen werden.", "es": "En la página del ticket, en Dependencias → Bloqueado por, usa Añadir un bloqueo…. Un ticket bloqueado no se puede reclamar.", "fr": "Sur la page du ticket, sous Dépendances → Bloqué par, utilisez Ajouter un bloqueur…. Un ticket bloqué ne peut pas être pris en charge.", "pt": "Na página do ticket, em Dependências → Bloqueado por, use Adicionar um bloqueador…. Um ticket bloqueado não pode ser assumido.", "tlh": "ticket navDaq, botwI''mey → botwI''Daq botwI'' yIchel… yIlo''. ticket botlu''bogh tlhaplu''laHbe''."}'::jsonb, '', '', '{}'::text[], 'blocked blocker dependency depends', 18),
  ('duplicate', '{"en": "How do I mark a duplicate?", "nl": "Hoe markeer ik een duplicaat?", "de": "Wie markiere ich ein Duplikat?", "es": "¿Cómo marco un duplicado?", "fr": "Comment marquer un doublon ?", "pt": "Como marco um duplicado?", "tlh": "chay'' velqa'' vIper?"}'::jsonb, '{"en": "On the ticket’s page, use Mark as duplicate… and pick the original. You can copy its labels and comments across.", "nl": "Gebruik op de ticketpagina Markeren als duplicaat… en kies het origineel. Je kunt de labels en reacties meekopiëren.", "de": "Nutze auf der Ticketseite „Als Duplikat markieren…“ und wähle das Original. Du kannst seine Labels und Kommentare mit hinüberkopieren.", "es": "En la página del ticket, usa Marcar como duplicado… y elige el original. Puedes copiar sus etiquetas y comentarios.", "fr": "Sur la page du ticket, utilisez Marquer comme doublon… et choisissez l’original. Vous pouvez y copier ses étiquettes et ses commentaires.", "pt": "Na página do ticket, use Marcar como duplicado… e escolha o original. Você pode copiar as etiquetas e os comentários dele.", "tlh": "ticket navDaq, velqa'' yIper… yIlo'' ''ej wa''DIch yIwIv. permeyDaj QInmeyDaj je Davelqa''moHlaH."}'::jsonb, '', '', '{}'::text[], 'duplicate same copy', 19),
  ('mention', '{"en": "How do I mention someone?", "nl": "Hoe vermeld ik iemand?", "de": "Wie erwähne ich jemanden?", "es": "¿Cómo menciono a alguien?", "fr": "Comment mentionner quelqu’un ?", "pt": "Como menciono alguém?", "tlh": "chay'' ghot vIpong?"}'::jsonb, '{"en": "Type @ in a comment and pick them. They’re notified, and it shows on their Mentions page.", "nl": "Typ @ in een reactie en kies de persoon. Die krijgt een melding en ziet het op de pagina Vermeldingen.", "de": "Tippe @ in einem Kommentar und wähle die Person aus. Sie wird benachrichtigt, und es erscheint auf ihrer Erwähnungen-Seite.", "es": "Escribe @ en un comentario y elígelos. Reciben una notificación y aparece en su página de Menciones.", "fr": "Tapez @ dans un commentaire et choisissez la personne. Elle est notifiée, et cela apparaît sur sa page Mentions.", "pt": "Digite @ em um comentário e escolha a pessoa. Ela é notificada, e isso aparece na página de Menções dela.", "tlh": "QInDaq @ yIghItlh ''ej yIwIv. ghuHmoHlu'', ''ej pongmey navchajDaq ''anglu''."}'::jsonb, '/mentions', '', '{}'::text[], 'mention tag @', 20),
  ('watch', '{"en": "How do I watch a ticket?", "nl": "Hoe volg ik een ticket?", "de": "Wie folge ich einem Ticket?", "es": "¿Cómo sigo un ticket?", "fr": "Comment suivre un ticket ?", "pt": "Como acompanho um ticket?", "tlh": "chay'' ticket vItlha''?"}'::jsonb, '{"en": "Mention yourself in a comment (type @ and your name). Anyone mentioned on a ticket hears about its comments, moves and finishing. To stop, press the mouth next to it on your Mentions page; press it again to watch again.", "nl": "Noem jezelf in een reactie (typ @ en je naam). Iedereen die op een ticket genoemd wordt, hoort over de reacties, verplaatsingen en afronding ervan. Om te stoppen druk je op de mond ernaast op je Vermeldingen-pagina; druk nog eens om weer te volgen.", "de": "Erwähne dich selbst in einem Kommentar (tippe @ und deinen Namen). Wer in einem Ticket erwähnt wird, erfährt von dessen Kommentaren, Verschiebungen und Abschluss. Zum Beenden drück auf deiner Erwähnungen-Seite auf den Mund daneben; drück erneut, um wieder zu folgen.", "es": "Menciónate en un comentario (escribe @ y tu nombre). Cualquiera mencionado en un ticket se entera de sus comentarios, movimientos y de cuándo se termina. Para dejar de seguirlo, pulsa la boca que hay al lado en tu página de Menciones; púlsala de nuevo para volver a seguirlo.", "fr": "Mentionnez-vous dans un commentaire (tapez @ et votre nom). Toute personne mentionnée sur un ticket est informée de ses commentaires, déplacements et de son achèvement. Pour arrêter, appuyez sur la bouche à côté sur votre page Mentions ; appuyez à nouveau pour le suivre de nouveau.", "pt": "Mencione a si mesmo em um comentário (digite @ e seu nome). Quem é mencionado em um ticket fica sabendo dos comentários, movimentações e conclusão dele. Para parar, clique na boca ao lado dele na sua página de Menções; clique de novo para voltar a acompanhar.", "tlh": "QInDaq ponglIj yIpong (@ ponglIj je yIghItlh). ticketDaq ponglu''bogh Hoch ghot QInmeyDaj, vIHghachmeyDaj, rInghachDaj je Qoy. DamevmeH, pongmeylIj navDaq retlhDaq nuj yI''uy; Datlha''qa''meH yI''uyqa''."}'::jsonb, '/mentions', '', '{}'::text[], 'watch follow subscribe unsubscribe mute notify', 21),
  ('attach', '{"en": "How do I attach files?", "nl": "Hoe voeg ik bestanden bij?", "de": "Wie hänge ich Dateien an?", "es": "¿Cómo adjunto archivos?", "fr": "Comment joindre des fichiers ?", "pt": "Como anexo arquivos?", "tlh": "chay'' ghItlhmey vIrar?"}'::jsonb, '{"en": "Use Attach files on a ticket. Up to 10 files of 10 MB each, and not while it’s in Done.", "nl": "Gebruik Bestanden bijvoegen op een ticket. Maximaal 10 bestanden van 10 MB, en niet terwijl het in Klaar staat.", "de": "Nutze „Dateien anhängen“ in einem Ticket. Bis zu 10 Dateien mit je 10 MB, und nicht, solange es in „Fertig“ ist.", "es": "Usa Adjuntar archivos en un ticket. Hasta 10 archivos de 10 MB cada uno, y no mientras esté en Hecho.", "fr": "Utilisez Joindre des fichiers sur un ticket. Jusqu’à 10 fichiers de 10 Mo chacun, et pas lorsqu’il est dans Terminé.", "pt": "Use Anexar arquivos em um ticket. Até 10 arquivos de 10 MB cada, e não enquanto ele estiver em Concluído.", "tlh": "ticketDaq ghItlhmey tIrar yIlo''. 10 ghItlhmey veH, Hoch 10 MB, ''ej rInDaq ghaHtaHvIS Qo''."}'::jsonb, '', '', '{}'::text[], 'attach file upload image screenshot', 22),
  ('search', '{"en": "How do I find a ticket?", "nl": "Hoe vind ik een ticket?", "de": "Wie finde ich ein Ticket?", "es": "¿Cómo encuentro un ticket?", "fr": "Comment trouver un ticket ?", "pt": "Como encontro um ticket?", "tlh": "chay'' ticket vItu''?"}'::jsonb, '{"en": "Use the search in the header (Ctrl+K or Cmd+K). It searches titles, details and comments; type a key like TL-123 to jump to it.", "nl": "Gebruik de zoekfunctie bovenaan (Ctrl+K of Cmd+K). Die doorzoekt titels, details en reacties; typ een code zoals TL-123 om er direct heen te gaan.", "de": "Nutze die Suche in der Kopfzeile (Strg+K oder Cmd+K). Sie durchsucht Titel, Details und Kommentare; tippe einen Schlüssel wie TL-123, um direkt dorthin zu springen.", "es": "Usa la búsqueda de la cabecera (Ctrl+K o Cmd+K). Busca en títulos, detalles y comentarios; escribe una clave como TL-123 para ir directamente a él.", "fr": "Utilisez la recherche dans l’en-tête (Ctrl+K ou Cmd+K). Elle porte sur les titres, détails et commentaires ; tapez une clé comme TL-123 pour y accéder directement.", "pt": "Use a pesquisa no cabeçalho (Ctrl+K ou Cmd+K). Ela pesquisa títulos, detalhes e comentários; digite uma chave como TL-123 para ir direto a ele.", "tlh": "nachDaq nejmeH jan yIlo'' (Ctrl+K pagh Cmd+K). pongmey, De''mey, QInmey nej; DaSupmeH TL-123 rur ngaQHa''moHwI'' yIghItlh."}'::jsonb, '', '', '{}'::text[], 'search find', 23),
  ('reports', '{"en": "Where are sprint reports?", "nl": "Waar zijn de sprintrapporten?", "de": "Wo sind die Sprintberichte?", "es": "¿Dónde están los informes de sprint?", "fr": "Où sont les rapports de sprint ?", "pt": "Onde ficam os relatórios de sprint?", "tlh": "nuqDaq sprint ja''ghachmey tu''lu''?"}'::jsonb, '{"en": "A board’s are under Past sprints → Sprint report; a project’s are in its header; the organization’s are in Settings (admins).", "nl": "Die van een bord staan onder Afgelopen sprints → Sprintrapport; die van een project bovenaan het project; die van de organisatie in Instellingen (beheerders).", "de": "Die eines Boards findest du unter Vergangene Sprints → Sprintbericht, die eines Projekts in seiner Kopfzeile, die der Organisation in den Einstellungen (Admins).", "es": "Los de un tablero están en Sprints anteriores → Informe del sprint; los de un proyecto, en su cabecera; los de la organización, en Ajustes (administradores).", "fr": "Ceux d’un tableau sont dans Sprints passés → Rapport de sprint ; ceux d’un projet sont dans son en-tête ; ceux de l’organisation sont dans Paramètres (administrateurs).", "pt": "Os de um quadro ficam em Sprints anteriores → Relatório da sprint; os de um projeto, no cabeçalho dele; os da organização, em Configurações (admins).", "tlh": "''echlet ja''ghachmey: sprintmey ret → sprint ja''ghach; jInmol ja''ghachmey: nachDaq; ghom''a'' ja''ghachmey: SeHlawDaq (loHwI''pu'')."}'::jsonb, '/docs/sprint-reports', '', ARRAY['board', 'project']::text[], 'report velocity burndown chart pdf', 24),
  ('invite', '{"en": "How do I invite people?", "nl": "Hoe nodig ik mensen uit?", "de": "Wie lade ich Leute ein?", "es": "¿Cómo invito a gente?", "fr": "Comment inviter des personnes ?", "pt": "Como convido pessoas?", "tlh": "chay'' ghotpu'' vIrI''?"}'::jsonb, '{"en": "Organization admins invite from Settings → Manage organization → Invite people. Free and Pro have up to 20 members; AI agents don’t count.", "nl": "Organisatiebeheerders nodigen uit via Instellingen → Organisatie beheren → Mensen uitnodigen. Free en Pro hebben maximaal 20 leden; AI-agents tellen niet mee.", "de": "Organisations-Admins laden über Einstellungen → Organisation verwalten → Leute einladen ein. Free und Pro haben bis zu 20 Mitglieder; KI-Agents zählen nicht mit.", "es": "Los administradores de la organización invitan desde Ajustes → Gestionar organización → Invitar personas. Free y Pro admiten hasta 20 miembros; los agentes de IA no cuentan.", "fr": "Les administrateurs de l’organisation invitent depuis Paramètres → Gérer l’organisation → Inviter des personnes. Free et Pro comptent jusqu’à 20 membres ; les agents IA ne comptent pas.", "pt": "Os admins da organização convidam em Configurações → Gerenciar organização → Convidar pessoas. Free e Pro têm até 20 membros; agentes de IA não contam.", "tlh": "SeHlaw → ghom''a'' yIloH → ghotpu'' tIrI'' vo'' rI'' ghom''a'' loHwI''pu''. 20 beqpu'' veH ghaj Free Pro je; AI vumwI''pu'' toghlu''be''."}'::jsonb, '/settings/organization', '', ARRAY['settings']::text[], 'invite member people add user', 25),
  ('teams', '{"en": "How do I set up teams and team leads?", "nl": "Hoe stel ik teams en teamleiders in?", "de": "Wie richte ich Teams und Teamleitungen ein?", "es": "¿Cómo configuro equipos y líderes de equipo?", "fr": "Comment configurer les équipes et leurs responsables ?", "pt": "Como configuro equipes e líderes de equipe?", "tlh": "chay'' beqmey beq DevwI''pu'' je vIcher?"}'::jsonb, '{"en": "In Settings → Manage organization → Teams: create a team, add members, Make leader, and link its boards. Organization admins only.", "nl": "In Instellingen → Organisatie beheren → Teams: maak een team, voeg leden toe, kies Leider maken en koppel de borden. Alleen organisatiebeheerders.", "de": "Unter Einstellungen → Organisation verwalten → Teams: Erstelle ein Team, füge Mitglieder hinzu, nutze „Zur Leitung machen“ und verknüpfe seine Boards. Nur Organisations-Admins.", "es": "En Ajustes → Gestionar organización → Equipos: crea un equipo, añade miembros, Nombrar líder y vincula sus tableros. Solo administradores de la organización.", "fr": "Dans Paramètres → Gérer l’organisation → Équipes : créez une équipe, ajoutez des membres, Nommer responsable, et liez ses tableaux. Administrateurs de l’organisation uniquement.", "pt": "Em Configurações → Gerenciar organização → Equipes: crie uma equipe, adicione membros, use Tornar líder e vincule os quadros dela. Somente admins da organização.", "tlh": "SeHlaw → ghom''a'' yIloH → beqmeyDaq: beq yIchenmoH, beqpu'' tIchel, DevwI'' yIchenmoH, ''echletmeyDaj tIrar. ghom''a'' loHwI''pu'' neH."}'::jsonb, '/settings/organization', '', ARRAY['settings']::text[], 'team lead leader', 26),
  ('holiday', '{"en": "How does it know who’s on holiday?", "nl": "Hoe weet het wie er op vakantie is?", "de": "Woher weiß es, wer im Urlaub ist?", "es": "¿Cómo sabe quién está de vacaciones?", "fr": "Comment sait-il qui est en congé ?", "pt": "Como ele sabe quem está de férias?", "tlh": "chay'' leSpoHDaq ghaHtaH ''Iv ''e'' Sov?"}'::jsonb, '{"en": "An organization admin connects Google Calendar in Settings → Integrations → Calendars; people away are marked in assigning and standup.", "nl": "Een organisatiebeheerder koppelt Google Calendar in Instellingen → Integraties → Agenda’s; wie afwezig is, wordt aangegeven bij toewijzen en in de stand-up.", "de": "Ein Organisations-Admin verbindet Google Calendar unter Einstellungen → Integrationen → Kalender; Abwesende werden beim Zuweisen und im Standup markiert.", "es": "Un administrador de la organización conecta Google Calendar en Ajustes → Integraciones → Calendarios; las personas ausentes se marcan al asignar y en el standup.", "fr": "Un administrateur de l’organisation connecte Google Agenda dans Paramètres → Intégrations → Agendas ; les personnes absentes sont signalées lors de l’assignation et du standup.", "pt": "Um admin da organização conecta o Google Calendar em Configurações → Integrações → Calendários; pessoas ausentes ficam marcadas na atribuição e no standup.", "tlh": "SeHlaw → rarghachmey → poH nav Daq Google Calendar rar ghom''a'' loHwI''; Qu'' nobmeH Qam ghomDaq je naDev ghobe''bogh ghotpu'' tu''lu''."}'::jsonb, '/docs/google-calendar', '', ARRAY['settings']::text[], 'holiday away leave vacation calendar', 27),
  ('repos', '{"en": "How do I link a GitHub repository?", "nl": "Hoe koppel ik een GitHub-repository?", "de": "Wie verknüpfe ich ein GitHub-Repository?", "es": "¿Cómo vinculo un repositorio de GitHub?", "fr": "Comment lier un dépôt GitHub ?", "pt": "Como vinculo um repositório do GitHub?", "tlh": "chay'' GitHub repository vIrar?"}'::jsonb, '{"en": "An admin connects GitHub or Bitbucket in Settings → Integrations, then links repos in Edit project → Repositories. Pull requests that mention a ticket’s key show on it, and merging finishes it.", "nl": "Een beheerder koppelt GitHub of Bitbucket in Instellingen → Integraties en koppelt daarna repository’s in Project bewerken → Repository’s. Pull requests die de ticketcode noemen staan bij het ticket, en mergen rondt het af.", "de": "Ein Admin verbindet GitHub oder Bitbucket unter Einstellungen → Integrationen und verknüpft dann Repos unter Projekt bearbeiten → Repositories. Pull Requests, die den Schlüssel eines Tickets nennen, erscheinen beim Ticket, und ein Merge schließt es ab.", "es": "Un administrador conecta GitHub o Bitbucket en Ajustes → Integraciones y luego vincula repos en Editar proyecto → Repositorios. Las pull requests que mencionan la clave de un ticket aparecen en él, y al fusionarlas se termina.", "fr": "Un administrateur connecte GitHub ou Bitbucket dans Paramètres → Intégrations, puis lie des dépôts dans Modifier le projet → Dépôts. Les pull requests qui mentionnent la clé d’un ticket s’affichent sur celui-ci, et leur fusion le termine.", "pt": "Um admin conecta o GitHub ou o Bitbucket em Configurações → Integrações e depois vincula repositórios em Editar projeto → Repositórios. Pull requests que mencionam a chave de um ticket aparecem nele, e o merge o conclui.", "tlh": "SeHlaw → rarghachmeyDaq GitHub pagh Bitbucket rar loHwI'', ghIq jInmol yIchoH → repositorymeyDaq repomey rar. pull requestmey ticket ngaQHa''moHwI'' pongbogh ticketDaq ''anglu'', ''ej mungDI'' rInmoH."}'::jsonb, '/projects/[project]/edit', '/settings/integrations', ARRAY['project', 'settings']::text[], 'github bitbucket repo repository pull request pr git', 28),
  ('api-keys', '{"en": "Where do I get an API key?", "nl": "Waar krijg ik een API-sleutel?", "de": "Wo bekomme ich einen API-Schlüssel?", "es": "¿Dónde consigo una clave de API?", "fr": "Où obtenir une clé API ?", "pt": "Onde consigo uma chave de API?", "tlh": "nuqDaq API ngaQHa''moHwI'' vIHevlaH?"}'::jsonb, '{"en": "Your own and AI agent keys are in Your settings → API keys. Service keys for integrations are in Settings → API keys, made by admins.", "nl": "Je eigen sleutels en die van AI-agents staan in Jouw instellingen → API-sleutels. Servicesleutels voor integraties staan in Instellingen → API-sleutels en worden door beheerders gemaakt.", "de": "Deine eigenen und die KI-Agent-Schlüssel findest du unter Deine Einstellungen → API-Schlüssel. Service-Schlüssel für Integrationen findest du unter Einstellungen → API-Schlüssel; sie werden von Admins erstellt.", "es": "Tus claves propias y las de agentes de IA están en Tus ajustes → Claves de API. Las claves de servicio para integraciones están en Ajustes → Claves de API, y las crean los administradores.", "fr": "Vos clés personnelles et celles de vos agents IA se trouvent dans Vos paramètres → Clés API. Les clés de service pour les intégrations se trouvent dans Paramètres → Clés API, créées par les administrateurs.", "pt": "Suas próprias chaves e as de agentes de IA ficam em Suas configurações → Chaves de API. As chaves de serviço para integrações ficam em Configurações → Chaves de API, criadas por admins.", "tlh": "SeHlawlIj → API ngaQHa''moHwI''meyDaq ngaQHa''moHwI''meylIj AI vumwI'' ngaQHa''moHwI''mey je tu''lu''. SeHlaw → API ngaQHa''moHwI''meyDaq rarghachmeyvaD QaH ngaQHa''moHwI''mey tu''lu'', loHwI''pu'' chenmoH."}'::jsonb, '/account/api-keys', '', ARRAY['account', 'settings']::text[], 'api key token', 29),
  ('ai-agent', '{"en": "How do I connect an AI agent?", "nl": "Hoe koppel ik een AI-agent?", "de": "Wie verbinde ich einen KI-Agent?", "es": "¿Cómo conecto un agente de IA?", "fr": "Comment connecter un agent IA ?", "pt": "Como conecto um agente de IA?", "tlh": "chay'' AI vumwI'' vIrar?"}'::jsonb, '{"en": "Make an AI key in Your settings → API keys, then use Connect AI to set up Claude Code, Codex, Cursor or others over MCP.", "nl": "Maak een AI-sleutel in Jouw instellingen → API-sleutels en gebruik daarna AI koppelen om Claude Code, Codex, Cursor of andere via MCP in te stellen.", "de": "Erstelle einen KI-Schlüssel unter Deine Einstellungen → API-Schlüssel und richte dann mit „KI verbinden“ Claude Code, Codex, Cursor oder andere über MCP ein.", "es": "Crea una clave de IA en Tus ajustes → Claves de API y luego usa Conectar IA para configurar Claude Code, Codex, Cursor u otros mediante MCP.", "fr": "Créez une clé IA dans Vos paramètres → Clés API, puis utilisez Connecter une IA pour configurer Claude Code, Codex, Cursor ou d’autres via MCP.", "pt": "Crie uma chave de IA em Suas configurações → Chaves de API e depois use Conectar IA para configurar Claude Code, Codex, Cursor ou outros via MCP.", "tlh": "SeHlawlIj → API ngaQHa''moHwI''meyDaq AI ngaQHa''moHwI'' yIchenmoH, ghIq MCP vegh Claude Code, Codex, Cursor latlh je DachermeH AI yIrar yIlo''."}'::jsonb, '/docs/mcp', '', ARRAY['account']::text[], 'ai agent claude codex cursor mcp', 30),
  ('roadmap', '{"en": "How do I make a roadmap?", "nl": "Hoe maak ik een roadmap?", "de": "Wie erstelle ich eine Roadmap?", "es": "¿Cómo hago una hoja de ruta?", "fr": "Comment créer une feuille de route ?", "pt": "Como faço um roadmap?", "tlh": "chay'' He nav vIchenmoH?"}'::jsonb, '{"en": "On the project page, open the Roadmaps tab → New roadmap. Admins publish it.", "nl": "Open op de projectpagina het tabblad Roadmaps → Nieuwe roadmap. Beheerders publiceren hem.", "de": "Öffne auf der Projektseite den Tab „Roadmaps“ → „Neue Roadmap“. Admins veröffentlichen sie.", "es": "En la página del proyecto, abre la pestaña Hojas de ruta → Nueva hoja de ruta. Los administradores la publican.", "fr": "Sur la page du projet, ouvrez l’onglet Feuilles de route → Nouvelle feuille de route. Les administrateurs la publient.", "pt": "Na página do projeto, abra a aba Roadmaps → Novo roadmap. Admins o publicam.", "tlh": "jInmol nachDaq, He navmey Sop yIpoSmoH → He nav chu''. loHwI''pu'' ngeH."}'::jsonb, '/projects/[project]', '/roadmaps', ARRAY['project']::text[], 'roadmap publish public', 31),
  ('requests', '{"en": "Can customers send us requests?", "nl": "Kunnen klanten ons aanvragen sturen?", "de": "Können Kunden uns Anfragen schicken?", "es": "¿Pueden los clientes enviarnos solicitudes?", "fr": "Les clients peuvent-ils nous envoyer des demandes ?", "pt": "Os clientes podem nos enviar solicitações?", "tlh": "maHvaD tlhobmey ngeHlaH''a'' DevaDpu''?"}'::jsonb, '{"en": "Yes: an admin turns on the Request form in Edit project. Requests arrive behind the Requests button on the project page.", "nl": "Ja: een beheerder zet het Aanvraagformulier aan in Project bewerken. Aanvragen komen binnen achter de knop Aanvragen op de projectpagina.", "de": "Ja: Ein Admin aktiviert das Anfrageformular unter „Projekt bearbeiten“. Anfragen landen hinter dem Button „Anfragen“ auf der Projektseite.", "es": "Sí: un administrador activa el formulario de solicitudes en Editar proyecto. Las solicitudes llegan tras el botón Solicitudes de la página del proyecto.", "fr": "Oui : un administrateur active le Formulaire de demande dans Modifier le projet. Les demandes arrivent derrière le bouton Demandes sur la page du projet.", "pt": "Sim: um admin ativa o Formulário de solicitações em Editar projeto. As solicitações chegam pelo botão Solicitações na página do projeto.", "tlh": "HIja'': jInmol yIchoHDaq tlhobmeH nav chu'' loHwI''. jInmol nachDaq tlhobmey leQ ''emDaq paw tlhobmey."}'::jsonb, '/projects/[project]/edit', '', ARRAY['project']::text[], 'request form customer feedback feature bug', 32),
  ('plan', '{"en": "How do I upgrade or change plan?", "nl": "Hoe upgrade ik of wijzig ik mijn abonnement?", "de": "Wie mache ich ein Upgrade oder wechsle den Tarif?", "es": "¿Cómo mejoro o cambio de plan?", "fr": "Comment passer à une offre supérieure ou changer d’offre ?", "pt": "Como faço upgrade ou mudo de plano?", "tlh": "chay'' nab vIDub pagh vIchoH?"}'::jsonb, '{"en": "Organization admins use the Plan card in Settings.", "nl": "Organisatiebeheerders gebruiken de kaart Plan in Instellingen.", "de": "Organisations-Admins nutzen die Karte „Tarif“ in den Einstellungen.", "es": "Los administradores de la organización usan la tarjeta Plan en Ajustes.", "fr": "Les administrateurs de l’organisation utilisent la carte Offre dans Paramètres.", "pt": "Os admins da organização usam o cartão Plano em Configurações.", "tlh": "SeHlawDaq nab ghItlhHom lo'' ghom''a'' loHwI''pu''."}'::jsonb, '/settings', '', ARRAY['settings']::text[], 'upgrade plan billing pro enterprise pay subscription', 33),
  ('theme', '{"en": "How do I switch to dark mode?", "nl": "Hoe schakel ik over naar donkere modus?", "de": "Wie wechsle ich in den dunklen Modus?", "es": "¿Cómo cambio al modo oscuro?", "fr": "Comment passer en mode sombre ?", "pt": "Como mudo para o modo escuro?", "tlh": "chay'' Hurgh mIwDaq vIleS?"}'::jsonb, '{"en": "Use the appearance button in the header: Light, Dark or System.", "nl": "Gebruik de weergaveknop bovenaan: Licht, Donker of Systeem.", "de": "Nutze den Darstellungs-Button in der Kopfzeile: Hell, Dunkel oder System.", "es": "Usa el botón de apariencia de la cabecera: Claro, Oscuro o Sistema.", "fr": "Utilisez le bouton d’apparence dans l’en-tête : Clair, Sombre ou Système.", "pt": "Use o botão de aparência no cabeçalho: Claro, Escuro ou Sistema.", "tlh": "nachDaq narghghach leQ yIlo'': wov, Hurgh pagh mIw motlh."}'::jsonb, '', '', '{}'::text[], 'dark light theme appearance', 34),
  ('language', '{"en": "Can I change the language?", "nl": "Kan ik de taal wijzigen?", "de": "Kann ich die Sprache ändern?", "es": "¿Puedo cambiar el idioma?", "fr": "Puis-je changer de langue ?", "pt": "Posso mudar o idioma?", "tlh": "Hol vIchoHlaH''a''?"}'::jsonb, '{"en": "When it’s available for you, choose it in Your settings → Language.", "nl": "Als het voor jou beschikbaar is, kies je het in Jouw instellingen → Taal.", "de": "Sobald sie für dich verfügbar ist, wähle sie unter Deine Einstellungen → Sprache.", "es": "Cuando esté disponible para ti, elígelo en Tus ajustes → Idioma.", "fr": "Lorsqu’elle sera disponible pour vous, choisissez-la dans Vos paramètres → Langue.", "pt": "Quando estiver disponível para você, escolha em Suas configurações → Idioma.", "tlh": "SoHvaD tu''lu''DI'', SeHlawlIj → HolDaq yIwIv."}'::jsonb, '/account', '', ARRAY['account']::text[], 'language dutch nederlands english', 35),
  ('notifications', '{"en": "How do I change my notifications?", "nl": "Hoe wijzig ik mijn meldingen?", "de": "Wie ändere ich meine Benachrichtigungen?", "es": "¿Cómo cambio mis notificaciones?", "fr": "Comment modifier mes notifications ?", "pt": "Como altero minhas notificações?", "tlh": "chay'' ghuHmeywIj vIchoH?"}'::jsonb, '{"en": "Open the bell in the header → Notification settings.", "nl": "Open de bel bovenaan → Meldingsinstellingen.", "de": "Öffne die Glocke in der Kopfzeile → Benachrichtigungseinstellungen.", "es": "Abre la campana de la cabecera → Ajustes de notificaciones.", "fr": "Ouvrez la cloche dans l’en-tête → Paramètres de notification.", "pt": "Abra o sino no cabeçalho → Configurações de notificação.", "tlh": "nachDaq ''In yIpoSmoH → ghuH SeHlaw."}'::jsonb, '/account', '', ARRAY['account']::text[], 'notification email bell', 36);
