-- TL-575: the help panel's answers, editable by staff in the admin panel. question and answer are
-- {"en": …, "nl": …} by locale (English required); pages are the page kinds it's suggested on.
CREATE TABLE help_answers (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    slug          TEXT NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9][a-z0-9-]*$'),
    question      JSONB NOT NULL CHECK (question->>'en' <> ''),
    answer        JSONB NOT NULL CHECK (answer->>'en' <> ''),
    href          TEXT NOT NULL DEFAULT '',
    fallback_href TEXT NOT NULL DEFAULT '',
    pages         TEXT[] NOT NULL DEFAULT '{}',
    words         TEXT NOT NULL DEFAULT '',
    position      INTEGER NOT NULL DEFAULT 0,
    published     BOOLEAN NOT NULL DEFAULT true,
    updated_by    TEXT NOT NULL DEFAULT '',
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

